        card("The letter d becomes r", "When the root word starts or ends with d, change it to r.", tables=[table(["Root word", "Noun (ka-an/han/nan)", "Meaning"], _R2, say=[])]),
        card("The letter e becomes i", "When the root word ends in e, change it to i.", tables=[table(["Root word", "Noun (ka-an/han/nan)", "Meaning"], _R3, say=[])]),
        card("2. Rules for choosing the suffix an/han/nan: an", "An is affixed to root words ending in a consonant.", tables=[table(["Root word", "Noun (ka-an/han/nan)", "Meaning"], _R4, say=[])]),
        card("Han", "Han is affixed to root words ending in a vowel (see the e to i table above): babae, kababaihan; lalake, kalalakihan; salbahe, kasalbahihan."),
