_A4 = [["Sino sa inyo ang may alam tungkol sa Balikatan sa Gapan, Nueva Ecija?", "ang may kaalaman", "Who has knowledge about the Balikatan in Gapan, Nueva Ecija?"], ["Maraming magagawa dahil malaki ang perang nakalaan para sa bagong programa ng nutrisyon sa mga liblib na nayon sa Laguna.", "dahil sa kalakihan ng perang", "Plenty will be done because of the big amount of money allocated for the new nutrition program in remote towns in Laguna."], ["Para maging ligtas sa sakit, kumain nang tama at mag-ehersisyo.", "Para sa kaligtasan sa sakit", "For safety against sickness, eat well and exercise."], ["May problema ba sa kalusugan dahil walang poso at kubeta sa ibang barangay?", "dahil sa kawalan ng", "Is there a health problem because of the lack of water pumps and toilets in other barangays?"], ["Una raw lulutasin ang suliraning likha ng dahilang walang malinis na tubig sa kanila.", "ang suliranin sa kawalan ng", "It is said that the problem of the lack of clean water in their localities will be solved first."], ["Ang marami di umano sa mga taga-rito ay kung saan-saan lang dumudumi.", "karamihan", "Allegedly, the majority of the people here move their bowels just about anywhere."]]
