_A6 = [("Sa iba pang balita, tumaas ang bilang ng kaso ng Human Immuno Deficiency Virus o ng HIV-Virus sa taong dalawang libo at labinlima.", "In other news, the number of cases of the Human Immuno Deficiency Virus, or HIV virus, rose in the year 2015."), ("Ayon sa Philippine HIV or Aids registry nasa mahigit pitong libong kaso na ang naitalang HIV cases sa loob lamang ng labing isang buwan sa taong dalawang libo at labinlima.", "According to the Philippine HIV or AIDS registry, more than seven thousand HIV cases have been recorded in just eleven months in the year 2015."), ("Tatlumpu’t walong porsiyento ang may HIV sa Metro Manila.", "Thirty-eight percent have HIV in Metro Manila."), ("Sinundan naman ito ng CALABARZON na may labinlimang porsiyento, labing-isang porsiyento sa Central Visayas, limang porsiyento naman sa Western Visayas.", "It was followed by CALABARZON with fifteen percent, eleven percent in Central Visayas, and five percent in Western Visayas."), ("Sa kabuuan, siyamnapu’t anim na porsiyento dito ay puro lalaki at may edad na dalawampu’t lima hanggang tatlumpu’t apat.", "In total, ninety-six percent of these are all male and aged twenty-five to thirty-four."), ("Isandaan at pitumpu’t apat na ang naitalang nasawi dahil sa naturang sakit.", "One hundred seventy-four deaths from the said disease have already been recorded.")]
