# ------------------------------------------------------------------ 7 listening 9-11
_L9 = [("Passage 1", "Isa sa mga pinakamahalagang pangangailangan ng mga mag-aaral ay ang palikuran. Ayon sa World Health Organization, isa sa limampu ang nararapat na toilet pupil ratio para sa mga kalalakihan sa mga pampublikong paaralan, habang isa sa dalawampu’t lima naman ang sa kababaihan. Pero ibang-iba ang nangyayari sa mga pampublikong paaralan sa bansa. Isa sa limampu’t lima ang toilet pupil ratio sa elementarya, habang isa sa siyamnapu’t tatlo naman sa high school. Kulang din ang mga paaralan sa mga hugasan ng kamay. Napakahalaga pa naman ang simpleng health practice na ito para maiwasan ang maraming mga sakit.", "One of the most important needs of students is the toilet. According to the World Health Organization, the proper toilet-pupil ratio for males in public schools is one to fifty, while for females it is one to twenty-five. But what happens in the country’s public schools is very different. The toilet-pupil ratio is one to fifty-five in elementary school, and one to ninety-three in high school. The schools also lack hand-washing facilities. And yet this simple health practice is very important to prevent many diseases."), ("Passage 2", "Sa nakaraang pag-aaral ng ADB aabot sa isang bilyon at pitong daang milyong tao sa Asya at Pasipiko ang nabubuhay sa maruming lugar. Walong daan at limampung milyon naman ang walang makuhanan ng malinis na inuming tubig habang pitong daan at walumpung milyon naman ang walang sariling palikuran. Habang pinag-uusapan ang kaunlaran ng mga bansa, nais ng ADB na maisama rin sa pag-unlad ang pagsasaayos ng mga palikuran, malinis na pamayanan at malinis na tubig para sa lahat.", "In a recent ADB study, up to one billion seven hundred million people in Asia and the Pacific live in dirty places. Eight hundred fifty million have nowhere to get clean drinking water, while seven hundred eighty million have no toilet of their own. While the development of countries is being discussed, the ADB wants the improvement of toilets, clean communities and clean water for all to be included in development as well.")]
_K9 = [("Passage 1: phrases about a public health concern", "kakulangan ng palikuran sa pampublikong paaralan; kulang ang mga paaralan sa mga hugasan ng kamay."), ("Passage 1: ka-an/han/nan nouns mentioned", "kalalakihan (male); kababaihan (female)."), ("Passage 2: phrases about public health concerns", "1.7 billion people live in dirty places; 850 million have no clean drinking water; 780 million have no toilet of their own."), ("Passage 2: the ADB’s aim", "While they talk about the development of (member) countries, they also want to include in the discussion the provision of toilets, clean communities and clean (drinking) water.")]
_L10 = [("Rey", "Sa panahon po ngayon, isa sa mabigat na problema talaga, Ms. Rhea, yung kakulangan sa pantustos sa pagkain ng maraming pamilya.", "In these times, one of the heavy problems really, Ms. Rhea, is the lack of funds for food of many families."), ("Rhea", "Sa katunayan, Rey, isa sa bawat sampung pamilya ay kulang ang kakayahan na bumili ng sapat at masustansiyang pagkain. Ang isang pamilya na may limang miyembro ay kailangan ng limang libo apat na raan at limampu’t walong piso kada buwan para matustusan ang kanilang pangangailangan sa pagkain lamang.", "In fact, Rey, one in every ten families lacks the ability to buy enough nutritious food. A family with five members needs five thousand four hundred fifty-eight pesos a month to meet its need for food alone."), ("Rey", "Katotohanan ho mga kaibigan. Narinig po ninyo, isa sa bawat sampu ang hindi sapat ang pambili ng sapat na pagkain. So ibig sabihin po nito, ay hindi po lahat ng pamilya ay may sapat na nutrisyon. Hindi po ba, Ms. Rhea?", "That is the truth, friends. You heard it, one in every ten does not have enough to buy enough food. So this means that not all families have enough nutrition. Isn’t that so, Ms. Rhea?"), ("Rhea", "Sa katunayan, halos pito sa bawat sampung pamilya naman ay kulang ang kinakain nila para sa pangangailangan sa enerhiya o energy requirements.", "In fact, almost seven in every ten families do not eat enough for their energy requirements."), ("Rey", "Ay, yayay. Napabuntong hininga ako nito, e. So, Ms. Rhea, ano-ano po ba ang sanhi ng hindi pagkakaroon ng sapat na pagkain ang ilan sa mga pamilya?", "Oh my. I sighed at this. So, Ms. Rhea, what are the causes of some families not having enough food?"), ("Rhea", "Maraming dahilan kung bakit lumalala ang problema sa kagutuman ng maraming Pilipino. Ilan sa mga ito ay kahirapan, ang mahihirap na pamilya ay walang lupa, kagamitan, o pera upang makabili ng pagkain dahil sa kakulangan ng kita sa trabaho o kawalan ng trabaho. Bukod dito ay ang pagkakaroon ng malaking pamilya, kung saan mas maraming miyembro ang mangangailangang maghati-hati sa pagkain. At siyempre, sa pagtaas ng presyo ng pagkain, na lubos na naaapektuhan ang mga pamilyang may maliit na panustos sa kanilang pang-araw-araw.", "There are many reasons why the problem of hunger among many Filipinos is getting worse. Some of these are poverty, poor families have no land, resources or money to buy food because of insufficient income from work or unemployment. Besides this is having a big family, where more members need to share the food. And of course, the rise in food prices, which greatly affects families with small provisions for their daily needs.")]
_K10 = [("1. The serious problem Rey wanted to discuss", "The shortage of funds to spend on food by many families."), ("2. Statistics offered", "One out of ten families lacks the ability to buy enough nutritious food. A family of five needs ₱5,458 per month for food only."), ("3. The consequence", "Since there is very little money to buy the required amount of food, not all families have the required nutrition (families go hungry)."), ("4. Statistics supporting number 3", "Seven out of ten families do not meet the required energy food intake."), ("5. At least three reasons for the worsening hunger", "(1) Poverty: poor families do not have land, resources or money to buy food; (2) insufficient income, unemployment, and a large family with more people to divide the food among; rising food prices."), ("6. Ka-an/han/nan nouns used", "(1) kakulangan, shortage; (2) katunayan, in fact; (3) kakayahan, ability; (4) katotohanan, reality (truth); (5) kagutuman, hunger; (6) kahirapan, poverty; (7) kagamitan, provisions (resources).")]
_L11 = [("Ayon naman sa World Health Organization isa sa anim na bata ang under weight sa developing countries.", "According to the World Health Organization, one in six children is underweight in developing countries."), ("Kung kaya’t dalawang milyon at anim na raang libong batang may edad na lima pababa ang namamatay sabi ng UNICEF.", "That is why two million six hundred thousand children aged five and below die, says UNICEF."), ("Natatantya naman ng United States Agency for International Development ang isang bilyong tao sa iba’t-ibang parte ng mundo na natutulog ng gutom at dalawang daang milyon dito ay mga bata.", "The United States Agency for International Development estimates one billion people in different parts of the world go to sleep hungry, and two hundred million of them are children."), ("Mga kababayan, panahon na tayo ay magtipid sa pagkain at magtulungan, magbigayan upang malabanan ang gutom at maiwasan ang pagsasayang ng pagkain.", "Countrymen, it is time for us to save food and help one another, to share with one another, to fight hunger and avoid wasting food.")]
